function(container, apiUrl, tables) {
  const inputField = container.querySelector('#input-daily-work');
  const charCountEl = container.querySelector('#char-count');
  const validationMsgEl = container.querySelector('#validation-message');
  const validationStatusEl = container.querySelector('#validation-status');
  const validationTextEl = container.querySelector('#validation-text');
  const submitStatusEl = container.querySelector('#submit-status');
  const emailStatusEl = container.querySelector('#email-status');
  const btnSubmit = container.querySelector('#btn-submit');
  const btnCancel = container.querySelector('#btn-cancel');
  const btnBackToDashboard = container.querySelector('#btn-back-to-dashboard');

  const MAX_CHARS = 2000;
  let isSubmitting = false;

  // Character count and validation
  inputField.addEventListener('input', function() {
    const length = this.value.length;
    charCountEl.textContent = length;

    // Validation: check if empty or only whitespace
    const isValid = this.value.trim().length > 0 && length <= MAX_CHARS;

    if (length === 0) {
      validationMsgEl.textContent = '業務内容を入力してください';
      validationMsgEl.style.display = 'block';
      validationMsgEl.style.color = '#d32f2f';
      btnSubmit.disabled = true;
      btnSubmit.style.opacity = '0.6';
      btnSubmit.style.cursor = 'not-allowed';
    } else if (length > MAX_CHARS) {
      validationMsgEl.textContent = `${length - MAX_CHARS}文字超過しています`;
      validationMsgEl.style.display = 'block';
      validationMsgEl.style.color = '#d32f2f';
      btnSubmit.disabled = true;
      btnSubmit.style.opacity = '0.6';
      btnSubmit.style.cursor = 'not-allowed';
    } else {
      validationMsgEl.textContent = '✓ 入力内容は有効です';
      validationMsgEl.style.display = 'block';
      validationMsgEl.style.color = '#4caf50';
      btnSubmit.disabled = false;
      btnSubmit.style.opacity = '1';
      btnSubmit.style.cursor = 'pointer';
    }
  });

  // Focus/Blur styling
  inputField.addEventListener('focus', function() {
    this.style.borderColor = 'var(--primary)';
    this.style.boxShadow = '0 0 0 2px rgba(44, 62, 80, 0.08)';
  });

  inputField.addEventListener('blur', function() {
    this.style.borderColor = 'rgba(229, 231, 235, 0.8)';
    this.style.boxShadow = 'none';
  });

  // Submit button
  btnSubmit.addEventListener('click', async function() {
    if (isSubmitting || !inputField.value.trim()) return;

    isSubmitting = true;
    btnSubmit.disabled = true;
    btnSubmit.style.opacity = '0.6';

    // Show validation status
    validationStatusEl.style.display = 'block';
    validationStatusEl.style.background = 'rgba(44, 62, 80, 0.05)';
    validationStatusEl.style.borderColor = 'rgba(44, 62, 80, 0.1)';
    validationTextEl.textContent = '日報を提出中...';

    try {
      // Get current user info (from tables or API)
      const userTable = tables.find(t => t.tableName === 'ユーザー');
      const currentUserId = userTable?.records?.[0]?.ユーザーID || 'unknown';

      // Prepare daily report data
      const reportData = {
        ユーザーID: currentUserId,
        報告日: new Date().toISOString().split('T')[0],
        業務内容: inputField.value.trim(),
        成果: '',
        課題: '',
        明日の予定: '',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      // Save daily report
      const dailyReportTableIndex = tables.findIndex(t => t.tableName === '日報');
      if (dailyReportTableIndex === -1) {
        throw new Error('日報テーブルが見つかりません');
      }

      const savedReport = await window.aivicApi.save(dailyReportTableIndex, reportData);

      if (!savedReport) {
        throw new Error('日報の保存に失敗しました');
      }

      // Prepare email notification data
      const emailData = {
        ユーザーID: currentUserId,
        メールタイプ: '日報提出通知',
        送信先メールアドレス: userTable?.records?.[0]?.メールアドレス || 'admin@example.com',
        件名: `【日報提出】${new Date().toLocaleDateString('ja-JP')}`,
        本文: `本日の日報が提出されました。\n\n【提出内容】\n${reportData.業務内容}`,
        送信日時: new Date().toISOString(),
        送信ステータス: '成功',
        関連日報ID: savedReport.id || savedReport.日報ID,
        再送信フラグ: false,
        作成日時: new Date().toISOString()
      };

      // Save email notification record
      const emailTableIndex = tables.findIndex(t => t.tableName === 'メール送信履歴');
      if (emailTableIndex !== -1) {
        await window.aivicApi.save(emailTableIndex, emailData);
      }

      // Show success message
      validationStatusEl.style.display = 'none';
      submitStatusEl.style.display = 'block';
      submitStatusEl.style.background = 'rgba(76, 175, 80, 0.08)';
      submitStatusEl.style.borderColor = 'rgba(76, 175, 80, 0.2)';
      submitStatusEl.style.color = '#2e7d32';
      submitStatusEl.innerHTML = '<span style="display: inline-block; width: 16px; height: 16px; background: #4caf50; border-radius: 50%; margin-right: 8px; vertical-align: middle;"></span>本日の日報を提出しました。管理者にメール通知が送信されます。';

      // Show email status
      emailStatusEl.style.display = 'block';

      // Auto-redirect after 3 seconds
      setTimeout(() => {
        window.showScreen('scr-1789983420567');
      }, 3000);

    } catch (error) {
      console.error('Error submitting report:', error);
      validationStatusEl.style.display = 'block';
      validationStatusEl.style.background = 'rgba(211, 47, 47, 0.08)';
      validationStatusEl.style.borderColor = 'rgba(211, 47, 47, 0.2)';
      validationStatusEl.style.color = '#c62828';
      validationTextEl.textContent = `エラーが発生しました: ${error.message}`;
      btnSubmit.disabled = false;
      btnSubmit.style.opacity = '1';
      isSubmitting = false;
    }
  });

  // Cancel button
  btnCancel.addEventListener('click', function() {
    if (inputField.value.trim()) {
      if (confirm('入力内容が破棄されます。よろしいですか？')) {
        inputField.value = '';
        charCountEl.textContent = '0';
        validationMsgEl.style.display = 'none';
        validationStatusEl.style.display = 'none';
        submitStatusEl.style.display = 'none';
        emailStatusEl.style.display = 'none';
        btnSubmit.disabled = true;
        btnSubmit.style.opacity = '0.6';
      }
    } else {
      window.showScreen('scr-1789983420567');
    }
  });

  // Back to dashboard link
  btnBackToDashboard.addEventListener('click', function() {
    window.showScreen('scr-1789983420567');
  });

  // Initial state: disable submit button
  btnSubmit.disabled = true;
  btnSubmit.style.opacity = '0.6';
  btnSubmit.style.cursor = 'not-allowed';
}

function(container, apiUrl, tables) {
  const statusMsg = container.querySelector('#status-message');
  const detailModal = container.querySelector('#detail-modal-overlay');
  const reminderModal = container.querySelector('#reminder-confirm-overlay');
  const closeDetailBtn = container.querySelector('#close-detail-modal');
  const cancelReminderBtn = container.querySelector('#cancel-reminder-btn');
  const confirmReminderBtn = container.querySelector('#confirm-reminder-btn');
  const sendReminderAllBtn = container.querySelector('[data-testid="send-reminder-all-btn"]');
  const saveSettingsBtn = container.querySelector('[data-testid="save-reminder-settings-btn"]');
  const searchInput = container.querySelector('[data-testid="search-submitted"]');
  const reminderTimeInput = container.querySelector('#reminder-time');
  const reminderMethodSelect = container.querySelector('[data-testid="reminder-method-select"]');

  let currentReminderTarget = null; // 'single' or 'all'
  let currentReminderUserId = null;

  // Show status message
  function showStatus(msg, duration = 5000) {
    statusMsg.textContent = msg;
    statusMsg.style.display = 'block';
    setTimeout(() => {
      statusMsg.style.display = 'none';
    }, duration);
  }

  // Close modals
  function closeModals() {
    detailModal.style.display = 'none';
    reminderModal.style.display = 'none';
  }

  closeDetailBtn.addEventListener('click', closeModals);
  cancelReminderBtn.addEventListener('click', closeModals);

  // Close on overlay click
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) closeModals();
  });
  reminderModal.addEventListener('click', (e) => {
    if (e.target === reminderModal) closeModals();
  });

  // Load submitted reports
  async function loadSubmittedReports() {
    const tbody = container.querySelector('#submitted-tbody');
    const countEl = container.querySelector('[data-testid="submitted-count"]');

    const reports = await window.aivicApi.list(1); // Table index 1: 日報
    if (!reports) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="4" style="padding: 20px; font-size: 12px;">データ取得に失敗しました</td></tr>';
      return;
    }

    const users = await window.aivicApi.list(0); // Table index 0: ユーザー
    const userMap = {};
    if (users) {
      users.forEach(u => {
        userMap[u.id] = u;
      });
    }

    // Filter by today
    const today = new Date().toISOString().split('T')[0];
    const todayReports = reports.filter(r => {
      const reportDate = new Date(r.created_at).toISOString().split('T')[0];
      return reportDate === today;
    });

    countEl.textContent = todayReports.length + '件';

    if (todayReports.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="4" style="padding: 20px; font-size: 12px;">本日の提出済み日報はありません</td></tr>';
      return;
    }

    tbody.innerHTML = todayReports.map(r => {
      const user = userMap[r.user_id];
      const userName = user ? user.name : '不明';
      const submittedTime = new Date(r.created_at).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
      const workSummary = (r.work_content || '').substring(0, 50) + (r.work_content && r.work_content.length > 50 ? '...' : '');

      return `
        <tr data-id="${r.id}" style="background: var(--bg-card); border-bottom: 1px solid var(--border); transition: background-color var(--motion-duration);">
          <td style="padding: 10px; color: var(--text); font-size: 13px;">${userName}</td>
          <td style="padding: 10px; color: var(--text); font-size: 13px;">${submittedTime}</td>
          <td style="padding: 10px; color: var(--text); font-size: 13px;">${workSummary}</td>
          <td style="padding: 10px; text-align: center;">
            <button class="view-detail-btn" data-id="${r.id}" style="background: transparent; border: 1px solid var(--border); color: var(--text); padding: 4px 8px; border-radius: var(--radius-control); font-size: 12px; cursor: pointer; transition: all var(--motion-duration);">
              詳細
            </button>
          </td>
        </tr>
      `;
    }).join('');

    // Attach detail button listeners
    container.querySelectorAll('.view-detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const reportId = e.target.dataset.id;
        const report = reports.find(r => r.id === reportId);
        if (report) {
          const user = userMap[report.user_id];
          container.querySelector('#detail-reporter').textContent = user ? user.name : '不明';
          container.querySelector('#detail-date').textContent = new Date(report.created_at).toLocaleDateString('ja-JP');
          container.querySelector('#detail-content').textContent = report.work_content || '-';
          detailModal.style.display = 'flex';
        }
      });
    });

    // Hover effect
    container.querySelectorAll('#submitted-tbody tr').forEach(tr => {
      tr.addEventListener('mouseenter', () => {
        tr.style.backgroundColor = '#f3f4f6';
      });
      tr.addEventListener('mouseleave', () => {
        tr.style.backgroundColor = 'var(--bg-card)';
      });
    });
  }

  // Load unsubmitted users
  async function loadUnsubmittedUsers() {
    const tbody = container.querySelector('#unsubmitted-tbody');
    const countEl = container.querySelector('[data-testid="unsubmitted-count"]');

    const logs = await window.aivicApi.list(3); // Table index 3: 日報未提出者検知ログ
    if (!logs) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="3" style="padding: 20px; font-size: 12px;">データ取得に失敗しました</td></tr>';
      return;
    }

    const users = await window.aivicApi.list(0); // Table index 0: ユーザー
    const userMap = {};
    if (users) {
      users.forEach(u => {
        userMap[u.id] = u;
      });
    }

    // Filter by today and not submitted
    const today = new Date().toISOString().split('T')[0];
    const todayUnsubmitted = logs.filter(log => {
      const logDate = new Date(log.target_date).toISOString().split('T')[0];
      return logDate === today && log.submission_status === 'unsubmitted';
    });

    // Deduplicate by user_id
    const uniqueUsers = {};
    todayUnsubmitted.forEach(log => {
      if (!uniqueUsers[log.user_id]) {
        uniqueUsers[log.user_id] = log;
      }
    });

    const unsubmittedList = Object.values(uniqueUsers);
    countEl.textContent = unsubmittedList.length + '件';

    if (unsubmittedList.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="3" style="padding: 20px; font-size: 12px;">未提出者はいません</td></tr>';
      return;
    }

    tbody.innerHTML = unsubmittedList.map(log => {
      const user = userMap[log.user_id];
      const userName = user ? user.name : '不明';
      const dept = user ? user.department : '-';

      return `
        <tr data-id="${log.user_id}" style="background: var(--bg-card); border-bottom: 1px solid var(--border); transition: background-color var(--motion-duration);">
          <td style="padding: 10px; color: var(--text); font-size: 13px;">${userName}</td>
          <td style="padding: 10px; color: var(--text); font-size: 13px;">${dept}</td>
          <td style="padding: 10px; text-align: center;">
            <button class="send-reminder-btn" data-user-id="${log.user_id}" style="background: transparent; border: 1px solid var(--border); color: var(--text); padding: 4px 8px; border-radius: var(--radius-control); font-size: 12px; cursor: pointer; transition: all var(--motion-duration);">
              送信
            </button>
          </td>
        </tr>
      `;
    }).join('');

    // Attach reminder button listeners
    container.querySelectorAll('.send-reminder-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const userId = e.target.dataset.userId;
        const user = userMap[userId];
        currentReminderTarget = 'single';
        currentReminderUserId = userId;
        container.querySelector('#reminder-confirm-message').textContent = `${user ? user.name : '不明'}さんにリマインダーを送信しますか？`;
        reminderModal.style.display = 'flex';
      });
    });

    // Hover effect
    container.querySelectorAll('#unsubmitted-tbody tr').forEach(tr => {
      tr.addEventListener('mouseenter', () => {
        tr.style.backgroundColor = '#f3f4f6';
      });
      tr.addEventListener('mouseleave', () => {
        tr.style.backgroundColor = 'var(--bg-card)';
      });
    });
  }

  // Send reminder
  confirmReminderBtn.addEventListener('click', async () => {
    if (currentReminderTarget === 'single' && currentReminderUserId) {
      const mailHistory = {
        user_id: currentReminderUserId,
        email_type: 'reminder',
        recipient_email: 'user@example.com',
        subject: '日報提出のお願い',
        body: '本日の日報をまだ提出されていません。お手数ですが提出をお願いします。',
        sent_at: new Date().toISOString(),
        send_status: 'success'
      };
      const saved = await window.aivicApi.save(4, mailHistory); // Table index 4: メール送信履歴
      if (saved) {
        showStatus('リマインダーを送信しました');
        closeModals();
        loadUnsubmittedUsers();
      }
    } else if (currentReminderTarget === 'all') {
      const logs = await window.aivicApi.list(3);
      const today = new Date().toISOString().split('T')[0];
      const todayUnsubmitted = logs.filter(log => {
        const logDate = new Date(log.target_date).toISOString().split('T')[0];
        return logDate === today && log.submission_status === 'unsubmitted';
      });

      let count = 0;
      for (const log of todayUnsubmitted) {
        const mailHistory = {
          user_id: log.user_id,
          email_type: 'reminder',
          recipient_email: 'user@example.com',
          subject: '日報提出のお願い',
          body: '本日の日報をまだ提出されていません。お手数ですが提出をお願いします。',
          sent_at: new Date().toISOString(),
          send_status: 'success'
        };
        const saved = await window.aivicApi.save(4, mailHistory);
        if (saved) count++;
      }
      showStatus(`リマインダーを ${count} 件送信しました`);
      closeModals();
      loadUnsubmittedUsers();
    }
  });

  // Bulk reminder
  sendReminderAllBtn.addEventListener('click', () => {
    currentReminderTarget = 'all';
    const countEl = container.querySelector('[data-testid="unsubmitted-count"]');
    const count = countEl.textContent;
    container.querySelector('#reminder-confirm-message').textContent = `未提出者全員（${count}）にリマインダーを送信しますか？`;
    reminderModal.style.display = 'flex';
  });

  // Save reminder settings
  saveSettingsBtn.addEventListener('click', async () => {
    const time = reminderTimeInput.value;
    const method = reminderMethodSelect.value;
    const days = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value)
      .join(',');

    if (!time || !method || !days) {
      showStatus('すべての項目を入力してください', 3000);
      return;
    }

    const settings = {
      user_id: 'current-user-id', // Should be current logged-in user
      enabled: true,
      send_time: time,
      send_days: days,
      send_method: method
    };

    const saved = await window.aivicApi.save(2, settings); // Table index 2: 日報リマインダー設定
    if (saved) {
      showStatus('リマインダー設定を保存しました');
    }
  });

  // Search submitted reports
  searchInput.addEventListener('input', async () => {
    const query = searchInput.value.toLowerCase();
    const rows = container.querySelectorAll('#submitted-tbody tr');
    rows.forEach(row => {
      const reporterName = row.querySelector('td:first-child').textContent.toLowerCase();
      row.style.display = reporterName.includes(query) ? '' : 'none';
    });
  });

  // Initial load
  loadSubmittedReports();
  loadUnsubmittedUsers();

  // Refresh every 30 seconds
  setInterval(() => {
    loadSubmittedReports();
    loadUnsubmittedUsers();
  }, 30000);
}
